<?php require 'includes/conexao.php'; require 'includes/verificar_login.php'; exigir_login(); $id=$_SESSION['usuario_id']; $stmt=$pdo->prepare('SELECT u.*,p.xp,p.nivel,p.percentual,COALESCE(SUM(r.pontuacao),0) pontos,COALESCE(SUM(r.acertos),0) acertos,COALESCE(SUM(r.erros),0) erros,COUNT(r.id) partidas FROM usuarios u JOIN progresso p ON p.usuario_id=u.id LEFT JOIN resultados r ON r.usuario_id=u.id WHERE u.id=? GROUP BY u.id,p.xp,p.nivel,p.percentual'); $stmt->execute([$id]); $d=$stmt->fetch(); $titulo='Meu perfil'; $home='dashboard.php'; include 'includes/header.php'; ?><div class="section-heading"><div><div class="eyebrow">Sua identidade na arena</div><h1 style="font-size:4rem">Meu perfil</h1></div></div><div class="two-col"><div class="card"><div class="icon">🌟</div><h2><?= htmlspecialchars($d['nome']) ?></h2><p><?= htmlspecialchars($d['email']) ?></p><span class="tag">Nível <?= $d['nivel'] ?></span><div class="progress-track"><div style="width:<?= $d['percentual'] ?>%"></div></div><small><?= $d['xp'] ?> XP acumulados</small></div><div class="card"><h3>Resumo da jornada</h3><p>Partidas realizadas: <strong><?= $d['partidas'] ?></strong></p><p>Pontuação total: <strong><?= $d['pontos'] ?></strong></p><p>Acertos: <strong style="color:var(--green)"><?= $d['acertos'] ?></strong></p><p>Erros: <strong style="color:var(--coral)"><?= $d['erros'] ?></strong></p></div></div><?php include 'includes/footer.php'; ?>
